<div class="section-heading"><div><span class="eyebrow">SUA JORNADA</span><h1>Meus pedidos<span class="accent">.</span></h1></div></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Data</th><th>Situação</th><th>Total</th><th></th></tr></thead><tbody><?php foreach ($rows as $p): ?><tr><td>#<?= e($p['id']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($p['created_at']))) ?></td><td><span class="badge"><?= e($p['status']) ?></span></td><td><?= money($p['total']) ?></td><td><a class="accent" href="<?= e(url('order',['id'=>$p['id']])) ?>">Ver detalhes ↗</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty">Você ainda não tem pedidos.</td></tr><?php endif; ?></tbody></table></div>
